import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Container,
    Paper,
    Typography,
    TextField,
    Button,
    Grid,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Alert,
    Box,
    Avatar,
    IconButton
} from '@mui/material';
import { PhotoCamera as PhotoCameraIcon } from '@mui/icons-material';
import axios from 'axios';

const API_URL = `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api`;

const PlayerCreate = () => {
    const navigate = useNavigate();
    const [error, setError] = useState('');
    const [imagePreview, setImagePreview] = useState(null);
    const [formData, setFormData] = useState({
        first_name: '',
        last_name: '',
        age: '',
        country: '',
        role: 'batsman',
        specialization: 'right_handed',
        base_price: '',
        profile_image: null
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prevState => ({
            ...prevState,
            [name]: value
        }));
    };

    const handleImageChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                setError('Image size should be less than 5MB');
                return;
            }
            setFormData(prev => ({
                ...prev,
                profile_image: file
            }));
            setImagePreview(URL.createObjectURL(file));
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem('token');
            const submitData = new FormData();
            
            submitData.append('first_name', formData.first_name);
            submitData.append('last_name', formData.last_name);
            submitData.append('age', parseInt(formData.age, 10));
            submitData.append('country', formData.country);
            submitData.append('role', formData.role);
            submitData.append('specialization', formData.specialization);
            submitData.append('base_price', parseFloat(formData.base_price));
            
            if (formData.profile_image) {
                submitData.append('profile_image', formData.profile_image);
            }

            await axios.post(
                `${API_URL}/players`,
                submitData,
                {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'multipart/form-data'
                    }
                }
            );
            navigate('/players');
        } catch (error) {
            console.error('Error details:', error.response?.data);
            setError(error.response?.data?.message || 'Error creating player');
        }
    };

    return (
        <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
            <Paper sx={{ p: 4 }}>
                <Typography variant="h4" gutterBottom>
                    Add New Player
                </Typography>

                {error && (
                    <Alert severity="error" sx={{ mb: 2 }}>
                        {error}
                    </Alert>
                )}

                <form onSubmit={handleSubmit}>
                    <Grid container spacing={3}>
                        <Grid item xs={12} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 2 }}>
                            <Box sx={{ position: 'relative' }}>
                                <Avatar
                                    src={imagePreview}
                                    sx={{ width: 120, height: 120, mb: 1 }}
                                />
                                <input
                                    accept="image/*"
                                    type="file"
                                    id="profile-image-input"
                                    onChange={handleImageChange}
                                    style={{ display: 'none' }}
                                />
                                <label htmlFor="profile-image-input">
                                    <IconButton
                                        color="primary"
                                        component="span"
                                        sx={{
                                            position: 'absolute',
                                            bottom: 0,
                                            right: 0,
                                            backgroundColor: 'background.paper'
                                        }}
                                    >
                                        <PhotoCameraIcon />
                                    </IconButton>
                                </label>
                            </Box>
                            <Typography variant="caption">Upload Profile Picture</Typography>
                        </Grid>

                        <Grid item xs={12} sm={6}>
                            <TextField
                                required
                                fullWidth
                                label="First Name"
                                name="first_name"
                                value={formData.first_name}
                                onChange={handleChange}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <TextField
                                required
                                fullWidth
                                label="Last Name"
                                name="last_name"
                                value={formData.last_name}
                                onChange={handleChange}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <TextField
                                required
                                fullWidth
                                label="Age"
                                name="age"
                                type="number"
                                value={formData.age}
                                onChange={handleChange}
                                inputProps={{ min: 16, max: 50 }}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <TextField
                                required
                                fullWidth
                                label="Country"
                                name="country"
                                value={formData.country}
                                onChange={handleChange}
                            />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <FormControl fullWidth required>
                                <InputLabel>Role</InputLabel>
                                <Select
                                    name="role"
                                    value={formData.role}
                                    onChange={handleChange}
                                    label="Role"
                                >
                                    <MenuItem value="batsman">Batsman</MenuItem>
                                    <MenuItem value="bowler">Bowler</MenuItem>
                                    <MenuItem value="all_rounder">All Rounder</MenuItem>
                                    <MenuItem value="wicket_keeper">Wicket Keeper</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <FormControl fullWidth required>
                                <InputLabel>Specialization</InputLabel>
                                <Select
                                    name="specialization"
                                    value={formData.specialization}
                                    onChange={handleChange}
                                    label="Specialization"
                                >
                                    <MenuItem value="right_handed">Right Handed</MenuItem>
                                    <MenuItem value="left_handed">Left Handed</MenuItem>
                                    <MenuItem value="fast">Fast</MenuItem>
                                    <MenuItem value="spin">Spin</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                            <TextField
                                required
                                fullWidth
                                label="Base Price"
                                name="base_price"
                                type="number"
                                value={formData.base_price}
                                onChange={handleChange}
                                inputProps={{ min: 0, step: 100000 }}
                            />
                        </Grid>
                    </Grid>

                    <Box sx={{ mt: 3, display: 'flex', gap: 2 }}>
                        <Button
                            variant="contained"
                            color="primary"
                            type="submit"
                        >
                            Create Player
                        </Button>
                        <Button
                            variant="outlined"
                            onClick={() => navigate('/players')}
                        >
                            Cancel
                        </Button>
                    </Box>
                </form>
            </Paper>
        </Container>
    );
};

export default PlayerCreate;