import React, { useState, useEffect } from 'react';
import {
    Container,
    Grid,
    Paper,
    Typography,
    TextField,
    Button,
    Box,
    Card,
    CardContent,
    CardMedia,
    CardActions,
    Alert,
    CircularProgress,
    Pagination,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Chip,
    Stack,
    Divider
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';

const API_URL = `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api`;

const getImageUrl = (url) => {
    if (!url) return '/default-player.png';
    // Only load images from our own backend (localhost or same domain)
    // External URLs (Wikimedia, placeholder sites) are untrusted and cause blinking
    if (url.startsWith('http') || url.startsWith('blob:')) {
        try {
            const parsed = new URL(url);
            const isLocal = parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1';
            if (!isLocal) return '/default-player.png'; // Skip external URLs
        } catch {
            return '/default-player.png';
        }
        return url; // localhost URL — safe to use
    }
    // Relative path like 'uploads/image.jpg' — prefix with backend base URL
    const baseUrl = API_URL.replace('/api', '');
    return `${baseUrl}${url.startsWith('/') ? '' : '/'}${url}`;
};

const PlayerList = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const [players, setPlayers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [page, setPage] = useState(1);
    const [filters, setFilters] = useState({
        role: '',
        country: '',
        status: '',
        specialization: ''
    });
    const playersPerPage = 12;

    useEffect(() => {
        const fetchPlayers = async () => {
            try {
                setLoading(true);
                setError('');
                const token = localStorage.getItem('token');

                if (!token) {
                    navigate('/login');
                    return;
                }

                const response = await axios.get(
                    `${API_URL}/players`,
                    {
                        headers: {
                            Authorization: `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        }
                    }
                );

                if (Array.isArray(response.data)) {
                    setPlayers(response.data);
                } else {
                    console.error('Unexpected API response format:', response.data);
                    setError('Unexpected data format received from server');
                }
                setLoading(false);
            } catch (err) {
                console.error('Error fetching players:', err);
                setError(err.response?.data?.message || 'Failed to fetch players');
                setPlayers([]);
                setLoading(false);

                if (err.response?.status === 401) {
                    navigate('/login');
                }
            }
        };

        fetchPlayers();
    }, [navigate]);

    const handleFilterChange = (event) => {
        const { name, value } = event.target;
        setFilters(prev => ({
            ...prev,
            [name]: value
        }));
        setPage(1); // Reset to first page when filters change
    };

    const filteredPlayers = players.filter(player => {
        const matchesSearch = (
            player?.first_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            player?.last_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            player?.role?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            player?.country?.toLowerCase().includes(searchTerm.toLowerCase())
        );

        const matchesRole = !filters.role || player?.role === filters.role;
        const matchesCountry = !filters.country || player?.country === filters.country;
        const matchesStatus = !filters.status || player?.status === filters.status;
        const matchesSpecialization = !filters.specialization || player?.specialization === filters.specialization;

        return matchesSearch && matchesRole && matchesCountry && matchesStatus && matchesSpecialization;
    });

    // Get unique values for filters
    const uniqueCountries = [...new Set(players.map(player => player.country))].filter(Boolean);
    const uniqueRoles = [...new Set(players.map(player => player.role))].filter(Boolean);
    const uniqueSpecializations = [...new Set(players.map(player => player.specialization))].filter(Boolean);

    // Calculate pagination
    const totalPages = Math.ceil(filteredPlayers.length / playersPerPage);
    const startIndex = (page - 1) * playersPerPage;
    const paginatedPlayers = filteredPlayers.slice(startIndex, startIndex + playersPerPage);

    const handlePageChange = (event, value) => {
        setPage(value);
        window.scrollTo(0, 0);
    };

    useEffect(() => {
        setPage(1);
    }, [searchTerm, filters]);

    if (loading) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="80vh">
                <CircularProgress />
            </Box>
        );
    }

    const getStatusColor = (status) => {
        switch (status?.toLowerCase()) {
            case 'available':
                return 'success';
            case 'sold':
                return 'error';
            case 'pending':
                return 'warning';
            default:
                return 'default';
        }
    };

    return (
        <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
            <Box sx={{ mb: 4 }} className="animate-fade-in">
                <Grid container spacing={2} alignItems="center" justifyContent="space-between">
                    <Grid item xs={12} md={8}>
                        <Typography variant="h3" component="h1" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #00d2ff 30%, #3a7bd5 90%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }} gutterBottom>
                            Players Directory
                        </Typography>
                    </Grid>
                    {user?.role === 'admin' && (
                        <Grid item xs={12} md={4} sx={{ textAlign: { xs: 'left', md: 'right' } }}>
                            <Button
                                variant="contained"
                                color="primary"
                                onClick={() => navigate('/players/create')}
                                sx={{ borderRadius: 8, px: 3, py: 1, fontWeight: 'bold' }}
                            >
                                + Add New Player
                            </Button>
                        </Grid>
                    )}
                </Grid>
            </Box>

            {error && (
                <Alert severity="error" sx={{ mb: 2, borderRadius: 2 }}>
                    {error}
                </Alert>
            )}

            <Paper className="glass-panel animate-fade-in" sx={{ p: 4, mb: 4, borderRadius: 4 }} style={{ animationDelay: '0.1s' }}>
                <Grid container spacing={3}>
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            label="Search Players"
                            variant="outlined"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder="Search by name, role, or country"
                        />
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                        <FormControl fullWidth>
                            <InputLabel>Role</InputLabel>
                            <Select
                                name="role"
                                value={filters.role}
                                onChange={handleFilterChange}
                                label="Role"
                            >
                                <MenuItem value="">All Roles</MenuItem>
                                {uniqueRoles.map(role => (
                                    <MenuItem key={role} value={role}>
                                        {role.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                        <FormControl fullWidth>
                            <InputLabel>Country</InputLabel>
                            <Select
                                name="country"
                                value={filters.country}
                                onChange={handleFilterChange}
                                label="Country"
                            >
                                <MenuItem value="">All Countries</MenuItem>
                                {uniqueCountries.map(country => (
                                    <MenuItem key={country} value={country}>{country}</MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                        <FormControl fullWidth>
                            <InputLabel>Status</InputLabel>
                            <Select
                                name="status"
                                value={filters.status}
                                onChange={handleFilterChange}
                                label="Status"
                            >
                                <MenuItem value="">All Status</MenuItem>
                                <MenuItem value="available">Available</MenuItem>
                                <MenuItem value="sold">Sold</MenuItem>
                                <MenuItem value="pending">Pending</MenuItem>
                            </Select>
                        </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                        <FormControl fullWidth>
                            <InputLabel>Specialization</InputLabel>
                            <Select
                                name="specialization"
                                value={filters.specialization}
                                onChange={handleFilterChange}
                                label="Specialization"
                            >
                                <MenuItem value="">All Specializations</MenuItem>
                                {uniqueSpecializations.map(spec => (
                                    <MenuItem key={spec} value={spec}>
                                        {spec.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                </Grid>
            </Paper>

            <Grid container spacing={3} className="animate-fade-in" style={{ animationDelay: '0.2s' }}>
                {paginatedPlayers.map((player) => (
                    <Grid item xs={12} sm={6} md={4} key={player.id}>
                        <Card className="glass-panel" sx={{ height: '100%', display: 'flex', flexDirection: 'column', transition: 'transform 0.3s, box-shadow 0.3s', '&:hover': { transform: 'translateY(-8px)', boxShadow: '0 12px 24px rgba(0, 210, 255, 0.2)' } }}>
                            <CardMedia
                                component="img"
                                height="200"
                                image={getImageUrl(player.profile_image_url)}
                                onError={(e) => { e.target.src = '/default-player.png'; }}
                                alt={`${player.first_name} ${player.last_name}`}
                                sx={{ objectFit: 'cover' }}
                            />
                            <CardContent sx={{ flexGrow: 1, p: 3 }}>
                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                                    <Typography variant="h5" component="h2" sx={{ fontWeight: 'bold' }}>
                                        {player.first_name} {player.last_name}
                                    </Typography>
                                    <Chip
                                        label={player.status}
                                        color={getStatusColor(player.status)}
                                        size="small"
                                        sx={{ fontWeight: 'bold' }}
                                    />
                                </Box>
                                <Stack spacing={1.5} sx={{ mt: 2 }}>
                                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                                        Role: <strong style={{color: 'white'}}>{player.role?.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}</strong>
                                    </Typography>
                                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                                        Specialization: <strong style={{color: 'white'}}>{player.specialization?.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}</strong>
                                    </Typography>
                                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                                        Country: <strong style={{color: 'white'}}>{player.country}</strong>
                                    </Typography>
                                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                                        Age: <strong style={{color: 'white'}}>{player.age} years</strong>
                                    </Typography>
                                    <Divider sx={{ borderColor: 'rgba(255,255,255,0.1)' }} />
                                    <Typography variant="body1" sx={{ color: '#00d2ff', fontWeight: 600 }}>
                                        Base Price: ₹{player.base_price?.toLocaleString() || 'N/A'}
                                    </Typography>
                                </Stack>
                            </CardContent>
                            <CardActions sx={{ px: 3, pb: 3, pt: 0 }}>
                                <Button
                                    variant="outlined"
                                    color="primary"
                                    onClick={() => navigate(`/players/${player.id}`)}
                                    sx={{ borderRadius: 8, width: '100%' }}
                                >
                                    View Details
                                </Button>
                            </CardActions>
                        </Card>
                    </Grid>
                ))}
            </Grid>

            {filteredPlayers.length === 0 && !loading && (
                <Box textAlign="center" py={4}>
                    <Typography variant="h6" color="text.secondary">
                        No players found matching your search criteria
                    </Typography>
                </Box>
            )}

            {filteredPlayers.length > 0 && (
                <Box display="flex" justifyContent="center" mt={4} mb={2}>
                    <Pagination
                        count={totalPages}
                        page={page}
                        onChange={handlePageChange}
                        color="primary"
                        size="large"
                    />
                </Box>
            )}
        </Container>
    );
};

export default PlayerList;