import React, { useState, useEffect } from 'react';
import {
    Container,
    Paper,
    Typography,
    Button,
    Box,
    Grid,
    Card,
    CardContent,
    Divider,
    CircularProgress,
    Alert
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import GroupsIcon from '@mui/icons-material/Groups';
import GavelIcon from '@mui/icons-material/Gavel';

// Add API URL constant
const API_URL = `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api`;

const Dashboard = () => {
    const navigate = useNavigate();
    const [user, setUser] = useState(JSON.parse(localStorage.getItem('user')));
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [stats, setStats] = useState(null);

    useEffect(() => {
        const fetchDashboardStats = async () => {
            try {
                setLoading(true);
                const token = localStorage.getItem('token');
                const response = await axios.get(`${API_URL}/dashboard/stats`, {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setStats(response.data);
            } catch (err) {
                setError(err.response?.data?.message || 'Error fetching dashboard statistics');
            } finally {
                setLoading(false);
            }
        };

        fetchDashboardStats();
    }, []);

    const handleLogout = async () => {
        try {
            const token = localStorage.getItem('token');
            await axios.post(`${API_URL}/auth/logout`, {}, {
                headers: { Authorization: `Bearer ${token}` }
            });
        } catch (err) {
            console.error('Logout error:', err);
        } finally {
            localStorage.removeItem('token');
            localStorage.removeItem('user');
            navigate('/login');
        }
    };

    const AdminActions = () => (
        <Box mt={4} className="animate-fade-in" style={{ animationDelay: '0.2s' }}>
            <Typography variant="h5" gutterBottom sx={{ fontWeight: 600, color: 'primary.main', mb: 3 }}>
                Admin Actions
            </Typography>
            <Grid container spacing={3}>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <EmojiEventsIcon color="primary" sx={{ mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">Tournament Management</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" color="primary" fullWidth onClick={() => navigate('/tournaments/create')} sx={{ mb: 1.5 }}>
                                    Create Tournament
                                </Button>
                                <Button variant="outlined" fullWidth onClick={() => navigate('/tournaments')} sx={{ borderColor: 'rgba(255,255,255,0.3)', color: 'white' }}>
                                    View All Tournaments
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <GroupsIcon color="secondary" sx={{ mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">Player Management</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" color="secondary" fullWidth onClick={() => navigate('/players/create')} sx={{ mb: 1.5 }}>
                                    Add New Player
                                </Button>
                                <Button variant="outlined" fullWidth onClick={() => navigate('/players')} sx={{ borderColor: 'rgba(255,255,255,0.3)', color: 'white' }}>
                                    Manage Players
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <GavelIcon sx={{ color: '#00d2ff', mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">Auction Management</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" fullWidth onClick={() => navigate('/auctions/create')} sx={{ mb: 1.5, background: 'linear-gradient(45deg, #00d2ff 30%, #3a7bd5 90%)' }}>
                                    Create Auction
                                </Button>
                                <Button variant="outlined" fullWidth onClick={() => navigate('/auctions')} sx={{ borderColor: 'rgba(255,255,255,0.3)', color: 'white' }}>
                                    View All Auctions
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );

    const TeamOwnerActions = () => (
        <Box mt={4} className="animate-fade-in" style={{ animationDelay: '0.2s' }}>
            <Typography variant="h5" gutterBottom sx={{ fontWeight: 600, color: 'primary.main', mb: 3 }}>
                Team Owner Actions
            </Typography>
            <Grid container spacing={3}>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <GroupsIcon color="primary" sx={{ mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">My Team</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" color="primary" fullWidth onClick={() => navigate('/teams/' + user.id)} sx={{ mb: 1.5 }}>
                                    View My Team
                                </Button>
                                <Button variant="outlined" fullWidth onClick={() => navigate('/players')} sx={{ borderColor: 'rgba(255,255,255,0.3)', color: 'white' }}>
                                    View My Players
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <GavelIcon color="secondary" sx={{ mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">Auctions</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" color="secondary" fullWidth onClick={() => navigate('/auctions')} sx={{ mb: 1.5 }}>
                                    View Active Auctions
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card className="glass-panel" sx={{ height: '100%', transition: 'transform 0.3s', '&:hover': { transform: 'translateY(-5px)' } }}>
                        <CardContent sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                                <EmojiEventsIcon sx={{ color: '#ffd700', mr: 1, fontSize: 32 }} />
                                <Typography variant="h6">Tournaments</Typography>
                            </Box>
                            <Box sx={{ mt: 'auto' }}>
                                <Button variant="contained" fullWidth onClick={() => navigate('/tournaments')} sx={{ mb: 1.5, background: 'linear-gradient(45deg, #00d2ff 30%, #3a7bd5 90%)' }}>
                                    View Tournaments
                                </Button>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );

    if (loading) {
        return (
            <Container maxWidth="lg">
                <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
                    <CircularProgress />
                </Box>
            </Container>
        );
    }

    return (
        <Container maxWidth="lg" className="animate-fade-in" sx={{ mb: 6 }}>
            <Box sx={{ p: { xs: 2, md: 4 }, mt: 4, borderRadius: 4 }} className="glass-panel">
                {error && (
                    <Alert severity="error" sx={{ mb: 3, borderRadius: 2 }}>
                        {error}
                    </Alert>
                )}

                <Box display="flex" justifyContent="space-between" alignItems="center" mb={4} flexWrap="wrap" gap={2}>
                    <Box>
                        <Typography variant="h3" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #00d2ff 30%, #3a7bd5 90%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
                            Welcome, {user?.username}!
                        </Typography>
                        <Typography variant="h6" color="textSecondary" sx={{ mt: 1 }}>
                            Role: {user?.role === 'admin' ? 'Administrator' : 'Team Owner'}
                        </Typography>
                    </Box>
                    <Button
                        variant="outlined"
                        color="error"
                        onClick={handleLogout}
                        sx={{ borderRadius: 8, px: 3, borderWidth: 2 }}
                    >
                        Logout
                    </Button>
                </Box>

                {stats && (
                    <Box mt={4} mb={5} className="animate-fade-in" style={{ animationDelay: '0.1s' }}>
                        <Grid container spacing={3}>
                            <Grid item xs={12} md={4}>
                                <Card className="glass-panel" sx={{ textAlign: 'center', py: 3, transition: 'transform 0.3s, box-shadow 0.3s', '&:hover': { transform: 'translateY(-5px)', boxShadow: '0 12px 40px rgba(0,210,255,0.2)' } }}>
                                    <CardContent>
                                        <GavelIcon sx={{ fontSize: 48, color: '#00d2ff', mb: 2 }} />
                                        <Typography color="textSecondary" gutterBottom sx={{ fontWeight: 500, letterSpacing: 1, textTransform: 'uppercase' }}>
                                            Active Auctions
                                        </Typography>
                                        <Typography variant="h2" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                                            {stats.activeAuctions}
                                        </Typography>
                                    </CardContent>
                                </Card>
                            </Grid>
                            <Grid item xs={12} md={4}>
                                <Card className="glass-panel" sx={{ textAlign: 'center', py: 3, transition: 'transform 0.3s, box-shadow 0.3s', '&:hover': { transform: 'translateY(-5px)', boxShadow: '0 12px 40px rgba(58,123,213,0.2)' } }}>
                                    <CardContent>
                                        <GroupsIcon sx={{ fontSize: 48, color: '#3a7bd5', mb: 2 }} />
                                        <Typography color="textSecondary" gutterBottom sx={{ fontWeight: 500, letterSpacing: 1, textTransform: 'uppercase' }}>
                                            Total Players
                                        </Typography>
                                        <Typography variant="h2" sx={{ fontWeight: 'bold', color: 'secondary.main' }}>
                                            {stats.totalPlayers}
                                        </Typography>
                                    </CardContent>
                                </Card>
                            </Grid>
                            <Grid item xs={12} md={4}>
                                <Card className="glass-panel" sx={{ textAlign: 'center', py: 3, transition: 'transform 0.3s, box-shadow 0.3s', '&:hover': { transform: 'translateY(-5px)', boxShadow: '0 12px 40px rgba(255,255,255,0.1)' } }}>
                                    <CardContent>
                                        <EmojiEventsIcon sx={{ fontSize: 48, color: '#ffd700', mb: 2 }} />
                                        <Typography color="textSecondary" gutterBottom sx={{ fontWeight: 500, letterSpacing: 1, textTransform: 'uppercase' }}>
                                            Active Tournaments
                                        </Typography>
                                        <Typography variant="h2" sx={{ fontWeight: 'bold', color: 'white' }}>
                                            {stats.activeTournaments}
                                        </Typography>
                                    </CardContent>
                                </Card>
                            </Grid>
                        </Grid>
                    </Box>
                )}

                <Divider sx={{ my: 4, borderColor: 'rgba(255,255,255,0.1)' }} />

                {user?.role === 'admin' ? <AdminActions /> : <TeamOwnerActions />}
            </Box>
        </Container>
    );
};

export default Dashboard;